class Solution:
    def twoSum(self, nums: List[int], idx: int, target) -> int:
        l, r = idx + 1, len(nums) - 1
        target -= nums[idx]
        count = 0

        while l < r:
            total = nums[l] + nums[r]
            if total < target:
                count += r - l
                l += 1
            else:
                r -= 1

        return count

    def threeSumSmaller(self, nums: list[int], target: int) -> list[list[int]]:
        # sort
        # O(n^3) -> O(n^2)
        n = len(nums)
        nums.sort()
        ans = 0

        for i in range(n):
            ans += self.twoSum(nums, i, target)

        return ans
